{
  "implementation": "def solve(case):
    attempts = case["attempts"]
    max_attempts = case["max_attempts"]
    n = len(attempts)
    any_success = any(a["success"] for a in attempts)
    if any_success:
        return {
            "decision": "stop",
            "memory_append": None,
            "next_attempt": n
        }
    if n >= max_attempts:
        return {
            "decision": "stop",
            "memory_append": None,
            "next_attempt": n
        }
    last = attempts[-1]
    return {
        "decision": "continue",
        "memory_append": {
            "reflection": last["reflection"],
            "signature": last["failure_signature"]
        },
        "next_attempt": n + 1
    }"
}
